const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/tothrowempty";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "throw.test.mjs"), [
  "import { test, expect } from 'vitest'",
  "test('empty string', () => {",
  "  expect(() => { throw new Error('boom') }).toThrow('')",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--reporter=json", "--outputFile=report.json"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const reportFile = path.join(dir, "report.json");
if (!fs.existsSync(reportFile)) {
  console.error("ERROR: vitest wrote no JSON report (exit " + r.status + ")");
  process.exit(2);
}
const report = JSON.parse(fs.readFileSync(reportFile, "utf8"));
const counts = "total " + report.numTotalTests + ", passed " + report.numPassedTests + ", failed " + report.numFailedTests;
console.log(counts);
if (report.numTotalTests === 1 && report.numPassedTests === 1 && r.status === 0) {
  console.log("PASS: toThrow('') passed for an error with message boom");
  process.exit(0);
}
if (report.numTotalTests === 1 && report.numFailedTests === 1) {
  console.error("FAIL: toThrow('') failed for an error with message boom");
  process.exit(1);
}
console.error("ERROR: unexpected result (" + counts + ", exit " + r.status + ")");
process.exit(2);

